54	function getCodexHome(env?: EnvOverrides): string {
55	  const homeDir = os.homedir?.();
56	  const defaultHome =
57	    typeof homeDir === 'string' && homeDir ? path.join(homeDir, '.codex') : undefined;
58	  const codexHome = getCodexEnvString(env, 'CODEX_HOME') || defaultHome || '.codex';
59	  return path.resolve(codexHome);
60	}
