129	function getCodexDefaultProvidersCacheKey(env?: EnvOverrides): string {
130	  return JSON.stringify({
131	    CODEX_HOME: getCodexEnvString(env, 'CODEX_HOME'),
132	    hasCodexApiKey: Boolean(getCodexEnvString(env, 'CODEX_API_KEY')),
133	    hasOpenAiApiKey: Boolean(getCodexEnvString(env, 'OPENAI_API_KEY')),
134	  });
135	}
