describe('Codex default providers (scratch)', () => {
  let codexHome: string;

  beforeEach(async () => {
    vi.useFakeTimers();
    mockProcessEnv({ CODEX_API_KEY: undefined, OPENAI_API_KEY: undefined });
    codexHome = fs.mkdtempSync(path.join(os.tmpdir(), 'promptfoo-codex-scratch-'));
    mockProcessEnv({ CODEX_HOME: codexHome });
    const { clearCodexDefaultProvidersForTesting } = await import(
