  });

  afterEach(async () => {
    const { clearCodexDefaultProvidersForTesting } = await import(
      '../../../src/providers/openai/codexDefaults'
    );
    clearCodexDefaultProvidersForTesting();
    vi.clearAllTimers();
    vi.useRealTimers();
    fs.rmSync(codexHome, { force: true, recursive: true });
    vi.restoreAllMocks();
  });

  it('partitions by resolved key; OPENAI precedence; rotation makes new entry', async () => {
    const { getCodexDefaultProviders } = await import('../../../src/providers/openai/codexDefaults');

    mockProcessEnv({ OPENAI_API_KEY: 'openai-1', CODEX_API_KEY: 'codex-a' });
    const a = getCodexDefaultProviders();
    expect((a.gradingProvider as OpenAICodexSDKProvider).apiKey).toBe('openai-1');
    expect((a.gradingProvider as OpenAICodexSDKProvider).getApiKey()).toBe('openai-1');

    // Only CODEX changes; OPENAI still wins -> same bundle
    mockProcessEnv({ OPENAI_API_KEY: 'openai-1', CODEX_API_KEY: 'codex-b' });
    const b = getCodexDefaultProviders();
    expect(b).toBe(a);

    // Rotate OPENAI -> new bundle
    mockProcessEnv({ OPENAI_API_KEY: 'openai-2', CODEX_API_KEY: 'codex-b' });
    const c = getCodexDefaultProviders();
    expect(c).not.toBe(a);
    expect((c.gradingProvider as OpenAICodexSDKProvider).apiKey).toBe('openai-2');
  });

  it('LRU bounds to 32 and evicts LRU with deferred shutdown', async () => {
    const shutdownSpy = vi
      .spyOn(OpenAICodexSDKProvider.prototype, 'shutdown')
      .mockResolvedValue(undefined);
    const { getCodexDefaultProviders } = await import('../../../src/providers/openai/codexDefaults');

    const first = ((): any => {
      mockProcessEnv({ CODEX_API_KEY: 'key-0' });
      return getCodexDefaultProviders();
    })();

    for (let i = 1; i <= 32; i++) {
      mockProcessEnv({ CODEX_API_KEY: `key-${i}` });
      getCodexDefaultProviders();
    }
    // 33 unique keys total (0..32) -> key-0 evicted. Shutdown deferred until timer.
    expect(shutdownSpy).not.toHaveBeenCalled();
    await vi.advanceTimersByTimeAsync(6_000);
    // 3 unique providers on the evicted bundle
    expect(shutdownSpy).toHaveBeenCalledTimes(3);
    void first;
  });

  it('defers shutdown while a call is in flight, then shuts down when idle', async () => {
    const deferred = createDeferred<any>();
    const callSpy = vi
      .spyOn(OpenAICodexSDKProvider.prototype, 'callApi')
      .mockReturnValue(deferred.promise);
    const shutdownSpy = vi
      .spyOn(OpenAICodexSDKProvider.prototype, 'shutdown')
      .mockResolvedValue(undefined);
    const { getCodexDefaultProviders } = await import('../../../src/providers/openai/codexDefaults');

    mockProcessEnv({ CODEX_API_KEY: 'ev-0' });
    const evicted = getCodexDefaultProviders();
    for (let i = 1; i <= 32; i++) {
      mockProcessEnv({ CODEX_API_KEY: `ev-${i}` });
      getCodexDefaultProviders();
    }

    // Start an in-flight call on the evicted bundle.
    const callPromise = evicted.gradingProvider.callApi('hi');
    expect(callSpy).toHaveBeenCalledTimes(1);

    // Timer fires while call in flight -> no shutdown yet.
    await vi.advanceTimersByTimeAsync(6_000);
    expect(shutdownSpy).not.toHaveBeenCalled();

    // Complete the call -> timer re-armed -> shutdown after grace.
    deferred.resolve({ output: 'ok' });
    await callPromise;
    expect(shutdownSpy).not.toHaveBeenCalled();
    await vi.advanceTimersByTimeAsync(6_000);
    expect(shutdownSpy).toHaveBeenCalledTimes(3);
  });

  it('resurrects a shut-down bundle on callApi (re-register 3, re-enter eviction)', async () => {
    const callSpy = vi
      .spyOn(OpenAICodexSDKProvider.prototype, 'callApi')
      .mockResolvedValue({ output: 'ok' } as any);
    const shutdownSpy = vi
      .spyOn(OpenAICodexSDKProvider.prototype, 'shutdown')
      .mockResolvedValue(undefined);
    const { getCodexDefaultProviders } = await import('../../../src/providers/openai/codexDefaults');

    mockProcessEnv({ CODEX_API_KEY: 'r-0' });
    const evicted = getCodexDefaultProviders();
    for (let i = 1; i <= 32; i++) {
      mockProcessEnv({ CODEX_API_KEY: `r-${i}` });
      getCodexDefaultProviders();
    }
    await vi.advanceTimersByTimeAsync(6_000);
    expect(shutdownSpy).toHaveBeenCalledTimes(3);

    const registerSpy = vi.spyOn(providerRegistry, 'register');
    const res = await evicted.gradingProvider.callApi('hi');
    expect(res).toEqual({ output: 'ok' });
    expect(registerSpy).toHaveBeenCalledTimes(3);
    expect(callSpy).toHaveBeenCalled();

    // Re-enters eviction cycle -> shuts down again after grace.
    await vi.advanceTimersByTimeAsync(6_000);
    expect(shutdownSpy).toHaveBeenCalledTimes(6);
  });

  it('clearForTesting cancels timers; in-flight finally cannot re-arm', async () => {
    const deferred = createDeferred<any>();
    vi.spyOn(OpenAICodexSDKProvider.prototype, 'callApi').mockReturnValue(deferred.promise);
    const shutdownSpy = vi
